const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
const accessToken = String(authHeader).replace(/^Bearer\s+/i, '').trim();
return [{ json: { accessToken } }];

const authUser = $('Verify Supabase Auth User').first().json || {};
const profile = $('Fetch Q-Ops User Profile').first().json || {};
const memberships = $items('Fetch Current User Project Memberships').map(i => i.json).filter(m => m && m.project_id);

if (!authUser.id || !profile.id || profile.status !== 'active') {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Missing or invalid Supabase Auth token.' } }];
}

const isAdmin = profile.role === 'admin';
const allowedProjectIds = new Set(memberships.map(m => String(m.project_id)));
const now = Date.now();
const dayAgo = now - 24 * 60 * 60 * 1000;
const todayStart = new Date();
todayStart.setHours(0, 0, 0, 0);
const todayStartMs = todayStart.getTime();

function inScope(row) {
  if (isAdmin) return true;
  const requestedBy = row.requested_by ? String(row.requested_by) : '';
  const projectId = row.project_id ? String(row.project_id) : '';
  return requestedBy === String(profile.id) && (!projectId || allowedProjectIds.has(projectId));
}
function ts(row) { return new Date(row.created_at || row.updated_at || row.checked_at || 0).getTime(); }
function statusOf(row) { return String(row.status || '').toLowerCase(); }
function isActive(status) { return ['queued', 'pending', 'processing', 'not_found'].includes(status); }
function isFailed(status) { return ['failed', 'error'].includes(status); }
function avg(values) { return values.length ? Math.round(values.reduce((a, b) => a + b, 0) / values.length) : 0; }

const generationJobs = $items('Fetch Generation Jobs').map(i => i.json).filter(j => j && j.job_id && inScope(j)).map(j => ({ ...j, pipeline: 'generation' }));
const ingestionJobs = $items('Fetch Ingestion Jobs').map(i => i.json).filter(j => j && j.job_id && inScope(j)).map(j => ({ ...j, pipeline: 'ingestion' }));
const allJobs = generationJobs.concat(ingestionJobs);
const activeJobs = allJobs.filter(j => isActive(statusOf(j)));
const pendingJobs = allJobs.filter(j => ['queued', 'pending', 'not_found'].includes(statusOf(j)));
const processingJobs = allJobs.filter(j => statusOf(j) === 'processing');
const failedJobsLast24h = allJobs.filter(j => isFailed(statusOf(j)) && ts(j) >= dayAgo);
const oldestPending = pendingJobs.map(ts).filter(Boolean).sort((a, b) => a - b)[0] || 0;

const metrics = $items('Fetch Recent Metrics').map(i => i.json).filter(m => m && m.id && inScope(m));
const recentMetrics24h = metrics.filter(m => ts(m) >= dayAgo);
const usageToday = metrics.filter(m => ts(m) >= todayStartMs);
const failedMetrics24h = metrics.filter(m => isFailed(statusOf(m)) && ts(m) >= dayAgo);
const durationValues = recentMetrics24h.map(m => Number(m.duration_ms || 0)).filter(Boolean);
const activeExecutionJobIds = new Set(activeJobs.map(j => j.job_id));

const latestServices = new Map();
for (const item of $items('Fetch Connection Results').map(i => i.json).filter(Boolean)) {
  const key = item.integration_key || item.service_name;
  if (!key || latestServices.has(key)) continue;
  const rawStatus = String(item.status || 'not_configured');
  const normalized = ['operational', 'ok', 'configured'].includes(rawStatus) ? 'ok' : rawStatus === 'degraded' ? 'degraded' : ['unreachable', 'unauthorized', 'error'].includes(rawStatus) ? 'error' : 'not_configured';
  latestServices.set(key, {
    name: item.service_name || item.integration_key || key,
    key,
    status: normalized,
    latencyMs: Number(item.latency_ms || 0),
    message: item.message || '',
    checkedAt: item.checked_at || null
  });
}
const services = Array.from(latestServices.values());
const unhealthyServices = services.filter(s => ['degraded', 'error', 'unreachable', 'unauthorized'].includes(s.status)).length;

const pendingCount = pendingJobs.length;
const processingCount = processingJobs.length;
const failedCount = failedJobsLast24h.length + failedMetrics24h.length;
const oldestPendingAgeSeconds = oldestPending ? Math.max(0, Math.round((now - oldestPending) / 1000)) : 0;
const avgLatency = avg(services.map(s => s.latencyMs).filter(Boolean));
const loadScore = Math.min(100, Math.round(
  pendingCount * 12 +
  processingCount * 18 +
  Math.min(30, oldestPendingAgeSeconds / 20) +
  failedCount * 10 +
  unhealthyServices * 15 +
  Math.min(15, avgLatency / 120)
));
const status = loadScore >= 75 || unhealthyServices >= 2 ? 'error' : loadScore >= 45 || unhealthyServices === 1 || failedCount > 0 ? 'degraded' : 'ok';
const jobsCompletedToday = usageToday.filter(m => String(m.event || '').includes('COMPLETED') || statusOf(m) === 'completed').length;

return [{ json: {
  status,
  score: loadScore,
  generatedAt: new Date().toISOString(),
  scope: isAdmin ? 'workspace' : 'self',
  queues: {
    pending: pendingCount,
    processing: processingCount,
    active: activeJobs.length,
    failedLast24h: failedJobsLast24h.length,
    oldestPendingAgeSeconds,
    generation: { pending: generationJobs.filter(j => ['queued', 'pending', 'not_found'].includes(statusOf(j))).length, processing: generationJobs.filter(j => statusOf(j) === 'processing').length },
    ingestion: { pending: ingestionJobs.filter(j => ['queued', 'pending', 'not_found'].includes(statusOf(j))).length, processing: ingestionJobs.filter(j => statusOf(j) === 'processing').length }
  },
  workflows: {
    activeExecutions: activeExecutionJobIds.size,
    failedLast24h: failedMetrics24h.length,
    avgDurationMs: avg(durationValues),
    recentMetricEvents: recentMetrics24h.length
  },
  services,
  usage: {
    tokensToday: usageToday.reduce((sum, m) => sum + Number(m.tokens_total || 0), 0),
    costTodayUsd: Number(usageToday.reduce((sum, m) => sum + Number(m.estimated_cost_usd || 0), 0).toFixed(6)),
    jobsCompletedToday
  },
  meta: { userRole: profile.role, projectIds: isAdmin ? [] : Array.from(allowedProjectIds) }
} }];
